export const financialManagementTextbookHtml = "\n  <div class=\"tkd-page-scope font-sans antialiased bg-[#FAF8F6] text-[#333333]\">\n\n    <!-- COVER HEADER CHO BẢN IN HOẶC XUẤT PDF A4 -->\n    <div class=\"print-document-header hidden print:block text-center border-b-2 border-[#8B1E2D] pb-4 mb-6\">\n      <div class=\"text-[12pt] font-semibold text-[#8B1E2D] tracking-wider uppercase\">TRƯỜNG CAO ĐẲNG KINH TẾ TP. HỒ CHÍ MINH — KHOA QUẢN TRỊ KINH DOANH</div>\n      <h1 class=\"text-[20pt] font-extrabold text-[#111827] uppercase tracking-tight mt-2 mb-1\">\n        GIÁO TRÌNH QUẢN TRỊ TÀI CHÍNH (MH21)\n      </h1>\n      <div class=\"text-[11pt] text-[#4B5563] italic\">\n        Tài liệu học tập chính quy bậc Cao đẳng &amp; Đại học — Chủ biên: ThS. NGUYỄN THỊ TRÚC PHƯƠNG\n      </div>\n      <div class=\"text-[10pt] text-[#6B7280] mt-2 flex justify-between items-center border-t border-[#E5E7EB] pt-1\">\n        <span>Mã học phần: MH21 (3 tín chỉ / 45 tiết)</span>\n        <span class=\"print-timestamp\">Năm học: <span class=\"js-current-year\"></span></span>\n        <span>Cổng học liệu số: NGUYỄN THỊ TRÚC PHƯƠNG</span>\n      </div>\n    </div>\n\n    <!-- HEADER BANNER ONLINE LUXURY RED TONE -->\n    <header class=\"no-print w-full bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#C62828] text-white py-8 sm:py-10 px-4 shadow-md border-b border-[#FCEEEF]/20\">\n      <div class=\"max-w-5xl mx-auto text-center space-y-2\">\n        <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/15 backdrop-blur-sm border border-white/25 text-xs font-semibold tracking-wider uppercase text-[#FCEEEF]\">\n          <span>📈</span> Giáo Trình Học Phần Trọng Tâm — Bậc Cao Đẳng &amp; Đại Học\n        </div>\n        <h1 class=\"text-xl sm:text-2xl md:text-3xl lg:text-4xl font-extrabold tracking-tight uppercase leading-tight text-white drop-shadow-xs m-0\">\n          GIÁO TRÌNH QUẢN TRỊ TÀI CHÍNH\n        </h1>\n        <p class=\"text-xs sm:text-sm text-[#FCEEEF]/90 max-w-3xl mx-auto font-medium leading-relaxed\">\n          Chủ biên: <strong>ThS. Nguyễn Thị Trúc Phương</strong> cùng nhóm tác giả ThS. Lê Thị Hồng Hà, ThS. Huỳnh Thị Quỳnh Tuyên — Khoa QTKD HCE. 8 chương toàn diện, tích hợp đầy đủ công thức tài chính KaTeX, mô hình DuPont, điểm hòa vốn, đòn bẩy DOL/DFL/DCL và định giá chứng khoán.\n        </p>\n      </div>\n    </header>\n\n    <!-- THANH ĐIỀU HƯỚNG NHANH -->\n    <div class=\"no-print bg-white border-b border-[#E8E0E1] sticky top-0 z-30 shadow-2xs\">\n      <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 py-2.5 flex flex-wrap items-center justify-between gap-2 text-xs\">\n        <div class=\"flex items-center gap-2\">\n          <a href=\"/study-corner\" class=\"inline-flex items-center gap-1.5 font-bold text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3 py-1.5 rounded-lg transition-colors\">\n            <span>←</span> Về Góc Học Tập\n          </a>\n          <a href=\"/study-corner/financial-management/intro\" class=\"inline-flex items-center gap-1.5 font-bold text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3 py-1.5 rounded-lg transition-colors\">\n            <span>📋</span> Giới Thiệu &amp; Đề Cương\n          </a>\n        </div>\n        <div class=\"flex items-center gap-2\">\n          <button type=\"button\" onclick=\"window.print()\" class=\"inline-flex items-center gap-1.5 font-bold text-[#8B1E2D] hover:bg-[#FCEEEF] border border-[#8B1E2D]/40 px-3 py-1.5 rounded-lg transition-all cursor-pointer\">\n            <span>🖨️</span> In Giáo Trình\n          </button>\n          <button type=\"button\" onclick=\"window.print()\" class=\"inline-flex items-center gap-1.5 font-bold text-white bg-[#8B1E2D] hover:bg-[#C62828] px-3 py-1.5 rounded-lg transition-all shadow-2xs cursor-pointer\">\n            <span>📄</span> Xuất PDF A4\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- KHUNG THÔNG TIN HỌC PHẦN -->\n    <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 pt-6\">\n      <div class=\"bg-white rounded-2xl border border-[#E8E0E1] p-4 sm:p-6 shadow-2xs grid grid-cols-2 sm:grid-cols-4 gap-4 text-center\">\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Mã Học Phần</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-[#8B1E2D]\">MH21</span>\n        </div>\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Khối Lượng</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-slate-900\">3 Tín Chỉ (45 Tiết)</span>\n        </div>\n        <div class=\"border-r border-[#E8E0E1] last:border-r-0\">\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Chủ Biên</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-[#8B1E2D]\">ThS. Nguyễn Thị Trúc Phương</span>\n        </div>\n        <div>\n          <span class=\"block text-2xs font-bold text-slate-500 uppercase tracking-wider\">Đơn Vị Quản Lý</span>\n          <span class=\"text-sm sm:text-base font-extrabold text-slate-900\">Khoa QTKD — HCE</span>\n        </div>\n      </div>\n    </div>\n\n    <!-- THÂN TRANG -->\n    <div class=\"max-w-5xl mx-auto px-3.5 sm:px-6 py-6 space-y-8\">\n\n      <!-- MỤC LỤC TỔNG THỂ -->\n      <nav aria-label=\"Mục lục giáo trình\" class=\"no-print rounded-3xl bg-white border border-[#E8E0E1] p-5 sm:p-8 shadow-sm\">\n        <div class=\"flex items-center justify-between gap-2 mb-4\">\n          <div class=\"flex items-center gap-2\">\n            <span class=\"px-3 py-1 rounded-full bg-[#FCEEEF] text-[#8B1E2D] text-xs font-bold tracking-wider uppercase\">Cấu Trúc Giáo Trình Chuẩn Hóa</span>\n          </div>\n          <span class=\"text-xs font-semibold text-slate-500\">8 Chương Chuyên Sâu</span>\n        </div>\n        <h2 class=\"text-xl sm:text-2xl font-extrabold text-[#111827] tracking-tight mb-4\">\n          MỤC LỤC TỔNG THỂ GIÁO TRÌNH QUẢN TRỊ TÀI CHÍNH\n        </h2>\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3\">\n          <a href=\"#chuong1\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">01</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Tổng quan quản trị tài chính</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Quan hệ tài chính, 3 quyết định lớn, mục tiêu tối đa hóa giá trị công ty.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong2\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">02</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Phân tích tài chính</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Báo cáo tài chính, 4 nhóm tỷ số tài chính then chốt và mô hình DuPont.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong3\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">03</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Hoạch định lợi nhuận</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Điểm hòa vốn kinh tế BEP, đòn bẩy DOL, DFL và đòn bẩy tổng hợp DCL.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong4\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">04</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Quản trị vốn lưu động</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Vốn lưu động ròng NWC, mô hình tồn kho EOQ, quản trị tiền mặt và phải thu.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong5\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">05</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Nguồn tài trợ doanh nghiệp</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Nguồn tài trợ ngắn hạn, dài hạn, tín dụng thương mại và thuê tài chính Leasing.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong6\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">06</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Giá trị tiền tệ theo thời gian</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Giá trị tương lai FV, giá trị hiện tại PV, niên kim dòng tiền đều và lãi suất EAR.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong7\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">07</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Định giá CK &amp; Chi phí vốn</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Định giá trái phiếu, cổ phiếu Gordon, mô hình CAPM và chi phí vốn WACC.</p>\n              </div>\n            </div>\n          </a>\n          <a href=\"#chuong8\" class=\"block p-3.5 rounded-2xl bg-[#FAF8F6] border border-[#E8E0E1] hover:border-[#8B1E2D] hover:bg-[#FCEEEF]/40 transition-all group no-underline text-[#333333]\">\n            <div class=\"flex items-start gap-3\">\n              <span class=\"w-8 h-8 rounded-xl bg-[#8B1E2D] text-white font-black text-xs flex items-center justify-center shrink-0 group-hover:bg-[#C62828] transition-colors shadow-2xs\">08</span>\n              <div>\n                <h3 class=\"font-bold text-[#111827] text-xs sm:text-sm group-hover:text-[#8B1E2D] mb-1\">Cơ cấu vốn doanh nghiệp</h3>\n                <p class=\"text-2xs text-[#666666] line-clamp-2\">Lý thuyết cơ cấu vốn Modigliani-Miller và phân tích điểm bàng quan EBIT-EPS.</p>\n              </div>\n            </div>\n          </a>\n        </div>\n      </nav>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 1: TỔNG QUAN VỀ QUẢN TRỊ TÀI CHÍNH                                 -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong1\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 01</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Tổng Quan Về Quản Trị Tài Chính\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Bản chất của quản trị tài chính, các quan hệ tài chính doanh nghiệp, 3 nhóm quyết định tài chính chiến lược, mục tiêu tối đa hóa giá trị doanh nghiệp và vai trò giám đốc tài chính CFO.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 1.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>1.1.</span> Bản Chất Của Quản Trị Tài Chính &amp; 3 Quyết Định Chiến Lược\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>Tài chính doanh nghiệp</strong> là hệ thống các quan hệ tiền tệ phát sinh trong quá trình tạo lập, phân phối và sử dụng các quỹ tiền tệ nhằm phục vụ cho mục tiêu sản xuất kinh doanh. Quản trị tài chính xoay quanh 3 nhóm quyết định lớn mang tính sống còn:\n            </p>\n            <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-3 my-3 text-xs\">\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">1. Quyết định đầu tư (Investment):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Doanh nghiệp nên mua sắm những tài sản nào? (Tài sản thực, nhà xưởng, mở rộng kinh doanh, mua sắm công nghệ hay đầu tư tài sản tài chính).</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">2. Quyết định tài trợ (Financing):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Huy động vốn từ nguồn nào để tài trợ cho tài sản? Sử dụng vốn nợ vay hay phát hành cổ phiếu mới? Cơ cấu vốn tối ưu là bao nhiêu?</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1\">\n                <strong class=\"text-[#8B1E2D]\">3. Quyết định phân phối (Dividend):</strong>\n                <p class=\"text-[#666666] m-0 leading-relaxed\">Bao nhiêu phần trăm lợi nhuận sau thuế sẽ được giữ lại để tái đầu tư, và bao nhiêu sẽ được chi trả cổ tức bằng tiền mặt hoặc cổ phiếu cho cổ đông?</p>\n              </div>\n            </div>\n            <div class=\"border-l-4 border-[#8B1E2D] bg-[#FCEEEF]/50 p-4 rounded-r-xl my-3 text-xs sm:text-sm\">\n              <strong class=\"text-[#8B1E2D] font-bold block mb-1\">Mục tiêu tối thượng của Quản trị tài chính:</strong>\n              <p class=\"m-0 leading-relaxed text-[#333333]\">\n                Không đơn thuần là \"tối đa hóa lợi nhuận kế toán\" trong ngắn hạn, mục tiêu bao trùm và khoa học nhất của tài chính hiện đại là <strong>Tối đa hóa giá trị doanh nghiệp</strong>, đồng nghĩa với việc <strong>tối đa hóa giá trị thị trường của vốn chủ sở hữu (giá cổ phiếu)</strong> của các cổ đông trong dài hạn.\n              </p>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 1\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Quản trị tài chính là việc cân đối hài hòa giữa khả năng sinh lời và an toàn thanh khoản, hướng đến việc gia tăng tài sản ròng bền vững cho các chủ sở hữu.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Phân tích 3 quyết định tài chính chủ yếu của doanh nghiệp và mối quan hệ hữu cơ giữa chúng?</li>\n              <li>Vì sao mục tiêu tối đa hóa giá trị công ty lại ưu việt hơn mục tiêu tối đa hóa lợi nhuận thuần túy?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <span class=\"text-slate-400\">← Bắt đầu giáo trình</span>\n            <a href=\"#chuong2\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 2: Phân Tích Tài Chính →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 2: PHÂN TÍCH TÀI CHÍNH                                             -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong2\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 02</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Phân Tích Tài Chính &amp; Mô Hình DuPont\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Hệ thống báo cáo tài chính, 4 nhóm tỷ số tài chính then chốt (Thanh toán, Hoạt động, Đòn bẩy tài chính, Khả năng sinh lời) và phương pháp phân tích mở rộng DuPont.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 2.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>2.1.</span> Hệ Thống Tỷ Số Tài Chính Then Chốt\n            </h3>\n\n            <div class=\"table-container overflow-x-auto my-3\">\n              <table class=\"w-full border-collapse border border-[#E8E0E1] text-xs\">\n                <thead>\n                  <tr class=\"bg-[#8B1E2D] text-white\">\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Nhóm chỉ tiêu</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/3\">Công thức tính toán</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-5/12\">Ý nghĩa kinh tế</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-[#E8E0E1]\">\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">1. Khả năng thanh toán hiện hành (CR)</td>\n                    <td class=\"p-2.5 font-mono\">CR = Tài sản ngắn hạn / Nợ ngắn hạn</td>\n                    <td class=\"p-2.5 text-[#333333]\">Đo lường năng lực chi trả nợ ngắn hạn bằng tài sản ngắn hạn (chuẩn thông thường ≥ 1.5 - 2.0).</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">2. Khả năng thanh toán nhanh (QR)</td>\n                    <td class=\"p-2.5 font-mono\">QR = (TSNH − Hàng tồn kho) / Nợ ngắn hạn</td>\n                    <td class=\"p-2.5 text-[#333333]\">Loại trừ tồn kho (tài sản khó thanh khoản nhất) để đo mức độ an toàn tiền tệ tức thời (chuẩn ≥ 1.0).</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">3. Vòng quay hàng tồn kho (ITO)</td>\n                    <td class=\"p-2.5 font-mono\">ITO = Giá vốn hàng bán / Tồn kho bình quân</td>\n                    <td class=\"p-2.5 text-[#333333]\">Số lần hàng tồn kho luân chuyển trong năm; phản ánh hiệu quả quản trị kho hàng.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">4. Kỳ thu tiền bình quân (DSO)</td>\n                    <td class=\"p-2.5 font-mono\">DSO = (Phải thu bình quân × 360) / Doanh thu</td>\n                    <td class=\"p-2.5 text-[#333333]\">Số ngày trung bình cần thiết để doanh nghiệp thu hồi được tiền bán chịu từ khách hàng.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">5. Tỷ số nợ trên tổng tài sản (D/A)</td>\n                    <td class=\"p-2.5 font-mono\">D/A = Tổng nợ phải trả / Tổng tài sản</td>\n                    <td class=\"p-2.5 text-[#333333]\">Tỷ trọng tài sản của doanh nghiệp được tài trợ bởi chủ nợ; đo lường rủi ro tài chính.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">6. Khả năng thanh toán lãi vay (ICR)</td>\n                    <td class=\"p-2.5 font-mono\">ICR = EBIT / Chi phí lãi vay (I)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Số lần lợi nhuận trước thuế và lãi vay bù đắp được chi phí lãi vay hàng năm.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">7. Tỷ suất sinh lời tài sản (ROA)</td>\n                    <td class=\"p-2.5 font-mono\">ROA = Lợi nhuận sau thuế (EAT) / Tổng tài sản bình quân</td>\n                    <td class=\"p-2.5 text-[#333333]\">Một đồng tài sản đưa vào hoạt động tạo ra bao nhiêu đồng lợi nhuận ròng.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">8. Tỷ suất sinh lời vốn CSH (ROE)</td>\n                    <td class=\"p-2.5 font-mono\">ROE = Lợi nhuận sau thuế (EAT) / Vốn CSH bình quân</td>\n                    <td class=\"p-2.5 text-[#333333]\">Chỉ số quan trọng nhất đối với cổ đông: Một đồng vốn tự có tạo ra bao nhiêu đồng lãi.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Section 2.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>2.2.</span> Mô Hình Phân Tích Mở Rộng DuPont\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Mô hình DuPont phân tách chỉ số ROE thành 3 nhân tố cấu thành, giúp nhận biết rõ động lực tăng trưởng lợi nhuận của doanh nghiệp đến từ đâu:\n            </p>\n            <div class=\"p-4 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] text-center my-3\">\n              <div class=\"font-mono font-bold text-xs sm:text-base text-[#8B1E2D]\">\n                ROE = (EAT / Doanh thu) × (Doanh thu / Tổng tài sản) × (Tổng tài sản / Vốn CSH)\n              </div>\n              <div class=\"font-bold text-xs text-[#111827] mt-2\">\n                ROE = Tỷ suất lãi ròng (ROS) × Hiệu suất sử dụng tài sản (AU) × Đòn bẩy tài chính (FL)\n              </div>\n            </div>\n            <p class=\"text-xs text-[#666666] leading-relaxed\">\n              Nhờ mô hình DuPont, CFO có thể tăng ROE bằng 3 cách: (1) Kiểm soát tốt chi phí để tăng ROS; (2) Tăng tốc độ quay vòng vốn để tăng AU; hoặc (3) Sử dụng đòn bẩy nợ hợp lý để khuếch đại lợi nhuận (nhưng cũng đồng thời tăng rủi ro thanh toán).\n            </p>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 2\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Phân tích tài chính là công cụ chẩn đoán sức khỏe doanh nghiệp, phát hiện sớm các nguy cơ mất khả năng thanh toán hoặc sử dụng tài sản lãng phí.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Phân tích ý nghĩa và cách tính các chỉ số thanh toán hiện hành (CR) và thanh toán nhanh (QR)?</li>\n              <li>Viết phương trình DuPont 3 nhân tố và giải thích ý nghĩa kinh tế của từng nhân tố đối với việc nâng cao ROE?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong1\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 1: Tổng Quan\n            </a>\n            <a href=\"#chuong3\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 3: Hoạch Định Lợi Nhuận →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 3: HOẠCH ĐỊNH LỢI NHUẬN & ĐÒN BẨY                                   -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong3\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 03</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Hoạch Định Lợi Nhuận &amp; Phân Tích Đòn Bẩy\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Phân loại chi phí theo hành vi, xác định điểm hòa vốn kinh tế (sản lượng và doanh thu), đòn bẩy kinh doanh DOL, đòn bẩy tài chính DFL và đòn bẩy tổng hợp DCL.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 3.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>3.1.</span> Phân Tích Điểm Hòa Vốn Kinh Tế (Breakeven Analysis)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Điểm hòa vốn là mức hoạt động mà tại đó Tổng doanh thu vừa đủ bù đắp Tổng chi phí, tức là Lợi nhuận trước thuế và lãi vay <strong>EBIT = 0</strong>.\n            </p>\n            <div class=\"bg-[#FAF8F6] border border-[#E8E0E1] rounded-xl p-4 my-3 text-xs sm:text-sm space-y-2\">\n              <strong class=\"text-[#8B1E2D] font-bold block\">Công thức xác định điểm hòa vốn:</strong>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                Sản lượng hòa vốn: Q_be = F / (P − V)\n              </div>\n              <div class=\"p-3 bg-white rounded-lg border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                Doanh thu hòa vốn: S_be = F / [ 1 − (V / P) ] = Q_be × P\n              </div>\n              <p class=\"text-2xs text-[#666666] m-0\">\n                Trong đó: $F$ là Tổng định phí kinh doanh; $P$ là Giá bán đơn vị sản phẩm; $V$ là Biến phí trên một đơn vị sản phẩm; $(P - V)$ là Số dư đảm phí đơn vị.\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 3.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>3.2.</span> Hệ Thống Đòn Bẩy (DOL, DFL, DCL)\n            </h3>\n            <div class=\"table-container overflow-x-auto my-3\">\n              <table class=\"w-full border-collapse border border-[#E8E0E1] text-xs\">\n                <thead>\n                  <tr class=\"bg-[#8B1E2D] text-white\">\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/4\">Loại đòn bẩy</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-1/3\">Công thức tính toán</th>\n                    <th class=\"border border-[#E8E0E1] p-2.5 text-left w-5/12\">Ý nghĩa kinh tế</th>\n                  </tr>\n                </thead>\n                <tbody class=\"divide-y divide-[#E8E0E1]\">\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">Đòn bẩy kinh doanh (DOL)</td>\n                    <td class=\"p-2.5 font-mono\">DOL = [ Q(P − V) ] / [ Q(P − V) − F ] = (S − VC) / EBIT</td>\n                    <td class=\"p-2.5 text-[#333333]\">Đo lường mức độ biến động của EBIT khi Doanh thu thay đổi 1%. Phản ánh rủi ro kinh doanh do định phí cố định tạo ra.</td>\n                  </tr>\n                  <tr class=\"bg-[#FAF8F6]\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">Đòn bẩy tài chính (DFL)</td>\n                    <td class=\"p-2.5 font-mono\">DFL = EBIT / (EBIT − I)</td>\n                    <td class=\"p-2.5 text-[#333333]\">Đo lường mức độ biến động của EPS khi EBIT thay đổi 1%. Phản ánh rủi ro tài chính do nợ vay tạo ra.</td>\n                  </tr>\n                  <tr class=\"bg-white\">\n                    <td class=\"p-2.5 font-bold text-[#8B1E2D]\">Đòn bẩy tổng hợp (DCL)</td>\n                    <td class=\"p-2.5 font-mono\">DCL = DOL × DFL = [ Q(P − V) ] / [ Q(P − V) − F − I ]</td>\n                    <td class=\"p-2.5 text-[#333333]\">Đo lường mức độ biến động tổng hợp của EPS khi Sản lượng tiêu thụ thay đổi 1%.</td>\n                  </tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 3\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Đòn bẩy là con dao hai lưỡi: Khi kinh doanh khởi sắc, đòn bẩy khuếch đại lợi nhuận vượt bậc; nhưng khi suy thoái, đòn bẩy làm thua lỗ gia tăng nhanh chóng.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Trình bày khái niệm và viết công thức tính sản lượng và doanh thu hòa vốn kinh tế?</li>\n              <li>So sánh bản chất của đòn bẩy kinh doanh DOL và đòn bẩy tài chính DFL?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong2\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 2: Phân Tích Tài Chính\n            </a>\n            <a href=\"#chuong4\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 4: Vốn Lưu Động →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 4: QUẢN TRỊ VỐN LƯU ĐỘNG                                            -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong4\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 04</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Quản Trị Vốn Lưu Động (Working Capital)\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Vốn lưu động thuần (NWC), quản trị tiền mặt (Mô hình Baumol, Miller-Orr), chính sách tín dụng thương mại &amp; quản trị khoản phải thu, mô hình đặt hàng kinh tế (EOQ).\n              </p>\n            </div>\n          </div>\n\n          <!-- Section 4.1 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>4.1.</span> Vốn Lưu Động Ròng &amp; Quản Trị Tiền Mặt\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>Vốn lưu động ròng (Net Working Capital - NWC) = Tài sản ngắn hạn − Nợ ngắn hạn</strong>. NWC dương thể hiện mức độ an toàn thanh khoản, cho thấy một phần tài sản ngắn hạn được tài trợ bằng nguồn vốn dài hạn vững chắc.\n            </p>\n            <div class=\"p-3 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] text-xs space-y-1\">\n              <strong class=\"text-[#8B1E2D]\">Mô hình quản trị tiền mặt Baumol:</strong>\n              <p class=\"text-[#333333] m-0\">\n                Xác định mức tồn quỹ tiền mặt tối ưu $C^*$ nhằm cân đối giữa chi phí giao dịch chuyển đổi chứng khoán và chi phí cơ hội giữ tiền mặt:\n              </p>\n              <div class=\"p-2.5 bg-white rounded border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                C* = √ [ (2 × T × F) / k ]\n              </div>\n              <p class=\"text-2xs text-[#666666] m-0\">Trong đó: $T$ là tổng nhu cầu tiền mặt trong kỳ; $F$ là chi phí giao dịch mỗi lần; $k$ là chi phí cơ hội (lãi suất).</p>\n            </div>\n          </div>\n\n          <!-- Section 4.2 -->\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>4.2.</span> Mô Hình Quản Trị Tồn Kho EOQ (Economic Order Quantity)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Mô hình EOQ xác định quy mô của mỗi lần đặt hàng ($Q^*$) sao cho <strong>Tổng chi phí tồn kho (Chi phí đặt hàng + Chi phí lưu kho) là nhỏ nhất</strong>:\n            </p>\n            <div class=\"p-4 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] text-center my-3\">\n              <div class=\"font-mono font-bold text-sm sm:text-base text-[#8B1E2D]\">\n                Q* = √ [ (2 × D × S) / H ]\n              </div>\n              <p class=\"text-2xs text-[#666666] mt-2 mb-0\">\n                Trong đó: $D$ là Tổng nhu cầu hàng tồn kho hàng năm; $S$ là Chi phí cố định cho mỗi lần đặt hàng; $H$ là Chi phí lưu kho đơn vị mỗi năm.\n              </p>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 4\n            </h4>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal\">\n              <li>Trình bày khái niệm vốn lưu động ròng NWC và ý nghĩa đối với an toàn thanh khoản?</li>\n              <li>Trình bày công thức và ý nghĩa của mô hình đặt hàng kinh tế EOQ?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong3\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 3: Hoạch Định Lợi Nhuận\n            </a>\n            <a href=\"#chuong5\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 5: Nguồn Tài Trợ →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 5: CÁC NGUỒN TÀI TRỢ CỦA DOANH NGHIỆP                               -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong5\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 05</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Các Nguồn Tài Trợ Doanh Nghiệp\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Nguồn tài trợ ngắn hạn (tín dụng thương mại, vay ngân hàng), nguồn tài trợ dài hạn (trái phiếu, cổ phiếu thường, cổ phiếu ưu đãi) và phương thức thuê tài chính (Financial Lease).\n              </p>\n            </div>\n          </div>\n\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>5.1.</span> Phân Loại Nguồn Vốn Tài Trợ\n            </h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs my-3\">\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">1. Nguồn vốn ngắn hạn (Dưới 1 năm):</strong>\n                <ul class=\"text-[#666666] pl-4 list-disc space-y-0.5 m-0\">\n                  <li><strong>Tín dụng thương mại:</strong> Mua chịu hàng từ nhà cung cấp (Khoản phải trả). Chi phí ẩn rất cao nếu từ bỏ chiết khấu thanh toán.</li>\n                  <li><strong>Vay ngắn hạn ngân hàng:</strong> Vay theo hạn mức tín dụng hoặc từng món có bảo đảm / tín chấp.</li>\n                  <li><strong>Nợ tích lũy:</strong> Lương phải trả người lao động, thuế phải nộp nhà nước.</li>\n                </ul>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">2. Nguồn vốn dài hạn (Trên 1 năm):</strong>\n                <ul class=\"text-[#666666] pl-4 list-disc space-y-0.5 m-0\">\n                  <li><strong>Vốn nợ dài hạn:</strong> Vay dài hạn các tổ chức tín dụng, phát hành Trái phiếu doanh nghiệp (Corporate Bonds).</li>\n                  <li><strong>Thuê tài chính (Leasing):</strong> Hình thức tín dụng trung dài hạn tài trợ máy móc thiết bị đặc chủng.</li>\n                  <li><strong>Vốn chủ sở hữu:</strong> Phát hành cổ phiếu thường, cổ phiếu ưu đãi và giữ lại lợi nhuận sau thuế tái đầu tư.</li>\n                </ul>\n              </div>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 5\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Lựa chọn nguồn tài trợ phải tuân thủ nguyên tắc khớp kỳ hạn: Dùng vốn dài hạn tài trợ tài sản cố định và phần thường xuyên của tài sản ngắn hạn.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Phân tích chi phí cơ hội của việc từ bỏ chiết khấu thanh toán trong tín dụng thương mại?</li>\n              <li>So sánh ưu nhược điểm giữa việc phát hành trái phiếu và phát hành cổ phiếu thường?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong4\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 4: Vốn Lưu Động\n            </a>\n            <a href=\"#chuong6\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 6: Giá Trị Tiền Tệ →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 6: GIÁ TRỊ TIỀN TỆ THEO THỜI GIAN                                   -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong6\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 06</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Giá Trị Tiền Tệ Theo Thời Gian (TVM)\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Lãi đơn và lãi kép, Giá trị tương lai (FV), Giá trị hiện tại (PV), Niên kim dòng tiền đều (Ordinary Annuity &amp; Annuity Due), Dòng tiền vô hạn và Lãi suất hiệu dụng thực tế (EAR).\n              </p>\n            </div>\n          </div>\n\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>6.1.</span> Các Công Thức Kinh Điển Về Giá Trị Tiền Tệ\n            </h3>\n\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs my-3\">\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">1. Giá trị tương lai của một khoản tiền (FV):</strong>\n                <div class=\"p-2.5 bg-white rounded border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                  FVₙ = PV × (1 + r)ⁿ\n                </div>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">2. Giá trị hiện tại của một khoản tiền (PV):</strong>\n                <div class=\"p-2.5 bg-white rounded border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                  PV = FVₙ / (1 + r)ⁿ = FVₙ × (1 + r)⁻ⁿ\n                </div>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">3. Giá trị hiện tại của chuỗi tiền đều cuối kỳ (PVA):</strong>\n                <div class=\"p-2.5 bg-white rounded border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                  PVA = A × [ 1 − (1 + r)⁻ⁿ ] / r\n                </div>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">4. Giá trị hiện tại của chuỗi tiền đều vô hạn (Perpetuity):</strong>\n                <div class=\"p-2.5 bg-white rounded border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                  PV = A / r\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 6\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> \"Một đồng tiền ngày hôm nay luôn có giá trị hơn một đồng tiền trong tương lai\" do yếu tố chi phí cơ hội, lạm phát và rủi ro bất định.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Viết công thức tính giá trị hiện tại (PV) và giá trị tương lai (FV) của một khoản tiền?</li>\n              <li>Nếu bạn muốn có 1 tỷ VNĐ sau 5 năm nữa với lãi suất 8%/năm ghép lãi hàng năm, hôm nay bạn phải gửi vào ngân hàng bao nhiêu tiền?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong5\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 5: Nguồn Tài Trợ\n            </a>\n            <a href=\"#chuong7\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 7: Định Giá &amp; WACC →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 7: ĐỊNH GIÁ CHỨNG KHOÁN & CHI PHÍ SỬ DỤNG VỐN                       -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong7\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 07</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Định Giá Chứng Khoán &amp; Chi Phí Vốn (WACC)\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Định giá trái phiếu doanh nghiệp, định giá cổ phiếu thường (Mô hình chiết khấu cổ tức Gordon DDM), mô hình định giá tài sản vốn (CAPM) và chi phí sử dụng vốn bình quân (WACC).\n              </p>\n            </div>\n          </div>\n\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>7.1.</span> Định Giá Trái Phiếu Và Cổ Phiếu Thường\n            </h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs my-3\">\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">Định giá trái phiếu trả lãi định kỳ:</strong>\n                <div class=\"p-2.5 bg-white rounded border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                  V_b = I × [ 1 − (1 + r_d)⁻ⁿ ] / r_d + M / (1 + r_d)ⁿ\n                </div>\n                <p class=\"text-2xs text-[#666666] m-0\">Trong đó: $I$ là tiền lãi hàng năm; $M$ là mệnh giá trái phiếu; $r_d$ là lãi suất thị trường.</p>\n              </div>\n              <div class=\"p-3.5 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] space-y-1.5\">\n                <strong class=\"text-[#8B1E2D]\">Định giá cổ phiếu thường (Mô hình Gordon):</strong>\n                <div class=\"p-2.5 bg-white rounded border border-[#E8E0E1] text-center font-mono font-bold text-[#8B1E2D]\">\n                  P₀ = D₁ / (r_e − g) = [ D₀ × (1 + g) ] / (r_e − g)\n                </div>\n                <p class=\"text-2xs text-[#666666] m-0\">Trong đó: $D_1$ là cổ tức kỳ vọng năm tới; $r_e$ là tỷ suất sinh lời kỳ vọng; $g$ là tốc độ tăng trưởng cổ tức bền vững.</p>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>7.2.</span> Chi Phí Sử Dụng Vốn Bình Quân (WACC)\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              <strong>WACC (Weighted Average Cost of Capital)</strong> là chi phí sử dụng vốn bình quân từ các nguồn tài trợ của doanh nghiệp, tính theo tỷ trọng giá trị thị trường:\n            </p>\n            <div class=\"p-4 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] text-center my-3\">\n              <div class=\"font-mono font-bold text-sm sm:text-base text-[#8B1E2D]\">\n                WACC = w_d × r_d × (1 − T) + w_p × r_p + w_e × r_e\n              </div>\n              <p class=\"text-2xs text-[#666666] mt-2 mb-0\">\n                Trong đó: $w_d, w_p, w_e$ là tỷ trọng Nợ, Cổ phiếu ưu đãi và Vốn cổ phần thường; $(1 - T)$ là lá chắn thuế lãi vay.\n              </p>\n            </div>\n          </div>\n\n          <!-- Summary & Navigation -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 7\n            </h4>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal\">\n              <li>Trình bày công thức định giá cổ phiếu thường theo mô hình Gordon và điều kiện áp dụng?</li>\n              <li>Viết công thức tính chi phí vốn bình quân WACC và giải thích tác động của lá chắn thuế $(1 - T)$?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong6\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 6: Giá Trị Tiền Tệ\n            </a>\n            <a href=\"#chuong8\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Chương 8: Cơ Cấu Vốn →\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- ========================================================================= -->\n      <!-- CHƯƠNG 8: CƠ CẤU VỐN CỦA DOANH NGHIỆP                                     -->\n      <!-- ========================================================================= -->\n      <section id=\"chuong8\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] overflow-hidden text-[#333333] transition-all\">\n        <div class=\"p-4 sm:p-7 space-y-6\">\n\n          <div class=\"chapter-header-banner rounded-2xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] p-5 sm:p-7 text-white shadow-md relative overflow-hidden\">\n            <div class=\"relative z-10 flex flex-col gap-2\">\n              <div class=\"inline-flex items-center gap-2 px-3 py-1 rounded-full bg-amber-400 text-slate-950 font-black text-xs uppercase tracking-wider w-fit\">\n                <span>CHƯƠNG 08</span>\n              </div>\n              <h2 class=\"text-xl sm:text-2xl md:text-3xl font-black tracking-tight uppercase leading-tight text-white m-0\">\n                Cơ Cấu Vốn Của Doanh Nghiệp\n              </h2>\n              <p class=\"text-xs sm:text-sm leading-relaxed max-w-3xl m-0 font-medium text-[#FCEEEF]\">\n                Lý thuyết cơ cấu vốn Modigliani-Miller (MM), lý thuyết đánh đổi (Trade-off Theory) và phương pháp phân tích điểm bàng quan EBIT-EPS.\n              </p>\n            </div>\n          </div>\n\n          <div class=\"space-y-3\">\n            <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-1.5 flex items-center gap-2\">\n              <span>8.1.</span> Phân Tích Điểm Bàng Quan EBIT — EPS\n            </h3>\n            <p class=\"text-xs sm:text-sm text-[#333333] leading-relaxed\">\n              Điểm bàng quan EBIT là mức lợi nhuận trước thuế và lãi vay mà tại đó hai phương án tài trợ khác nhau (Phương án dùng Nợ vay và Phương án dùng Vốn cổ phần) mang lại <strong>Thu nhập trên mỗi cổ phần EPS như nhau</strong>:\n            </p>\n            <div class=\"p-4 bg-[#FAF8F6] rounded-xl border border-[#E8E0E1] text-center my-3\">\n              <div class=\"font-mono font-bold text-xs sm:text-sm text-[#8B1E2D]\">\n                [ (EBIT − I₁) × (1 − T) ] / n₁ = [ (EBIT − I₂) × (1 − T) ] / n₂\n              </div>\n              <p class=\"text-2xs text-[#666666] mt-2 mb-0\">\n                <em>Quy tắc quyết định:</em> Nếu EBIT kỳ vọng trong tương lai lớn hơn điểm bàng quan EBIT*, phương án sử dụng nợ vay sẽ mang lại EPS cao hơn; ngược lại nếu EBIT thấp hơn, nên chọn vốn cổ phần để tránh rủi ro phá sản.\n              </p>\n            </div>\n          </div>\n\n          <!-- Summary & Questions -->\n          <div class=\"bg-[#FAF8F6] border border-[#8B1E2D]/30 rounded-2xl p-4 sm:p-5 my-4\">\n            <h4 class=\"text-xs sm:text-sm font-extrabold text-[#8B1E2D] uppercase tracking-wider mb-2 flex items-center gap-2\">\n              <span>📌</span> Tóm Tắt &amp; Câu Hỏi Ôn Tập Chương 8\n            </h4>\n            <p class=\"text-xs text-[#333333] leading-relaxed\">\n              <strong>Tóm tắt:</strong> Cơ cấu vốn tối ưu là cơ cấu phối hợp giữa nợ và vốn cổ phần sao cho tối thiểu hóa WACC và tối đa hóa giá trị doanh nghiệp.\n            </p>\n            <ol class=\"text-xs text-[#333333] space-y-1 pl-4 list-decimal mt-2\">\n              <li>Trình bày định đề MM trong điều kiện có thuế thu nhập doanh nghiệp? Vai trò của lá chắn thuế nợ vay?</li>\n              <li>Ý nghĩa của việc xác định điểm bàng quan EBIT-EPS trong việc lựa chọn phương án tài trợ nợ hay cổ phần?</li>\n            </ol>\n          </div>\n\n          <div class=\"flex items-center justify-between gap-2 pt-4 border-t border-[#E8E0E1] text-xs font-bold\">\n            <a href=\"#chuong7\" class=\"inline-flex items-center gap-1 text-slate-700 hover:text-[#8B1E2D] bg-slate-100 px-3.5 py-2 rounded-xl transition-all\">\n              ← Chương 7: Định Giá &amp; WACC\n            </a>\n            <a href=\"#tailieuthamkhao\" class=\"inline-flex items-center gap-1 text-[#8B1E2D] hover:text-[#C62828] bg-[#FCEEEF] px-3.5 py-2 rounded-xl transition-all\">\n              Tài Liệu Tham Khảo ↓\n            </a>\n          </div>\n\n        </div>\n      </section>\n\n      <!-- TÀI LIỆU THAM KHẢO CHÍNH THỨC -->\n      <section id=\"tailieuthamkhao\" class=\"bg-white rounded-2xl shadow-sm border border-[#E8E0E1] p-5 sm:p-7 space-y-3\">\n        <h3 class=\"text-base sm:text-lg font-extrabold text-[#8B1E2D] border-b border-[#E8E0E1] pb-2 flex items-center gap-2\">\n          <span>📚</span> Tài Liệu Tham Khảo Chính Thức Môn Học\n        </h3>\n        <ol class=\"text-xs text-[#333333] space-y-2 pl-4 list-decimal leading-relaxed\">\n          <li><strong>Nguyễn Thị Trúc Phương (Chủ biên), Lê Thị Hồng Hà, Huỳnh Thị Quỳnh Tuyên (2021)</strong>, <em>Giáo trình Quản trị tài chính</em>, Trường Cao đẳng Kinh tế TP. Hồ Chí Minh (HCE).</li>\n          <li><strong>Trần Ngọc Thơ (2020)</strong>, <em>Tài chính doanh nghiệp hiện đại</em>, NXB Kinh Tế TP. Hồ Chí Minh.</li>\n          <li><strong>Nguyễn Minh Kiều (2019)</strong>, <em>Quản trị tài chính doanh nghiệp</em>, NXB Tài Chính.</li>\n          <li><strong>Brigham, E. F., &amp; Ehrhardt, M. C. (2020)</strong>, <em>Financial Management: Theory &amp; Practice</em>, Cengage Learning.</li>\n          <li><strong>Brealey, R. A., Myers, S. C., &amp; Allen, F. (2020)</strong>, <em>Principles of Corporate Finance</em>, McGraw-Hill Education.</li>\n        </ol>\n      </section>\n\n      <!-- KHUNG XÁC NHẬN IN ẤN VÀ XUẤT HỌC LIỆU A4 -->\n      <div class=\"no-print mt-10 p-6 sm:p-8 rounded-3xl bg-gradient-to-r from-[#8B1E2D] via-[#A32234] to-[#691420] text-white shadow-md text-center space-y-3\">\n        <div class=\"flex items-center justify-center gap-2\">\n          <span class=\"text-xl\">📚</span>\n          <h3 class=\"text-base sm:text-lg font-bold text-white m-0\">In Ấn Và Xuất Học Liệu Giáo Trình Khổ A4</h3>\n        </div>\n        <p class=\"text-xs sm:text-sm text-[#FCEEEF] max-w-xl mx-auto m-0 leading-relaxed\">\n          Tài liệu chuẩn hóa phục vụ sinh viên ôn tập, nghiên cứu và in ấn theo tiêu chuẩn giáo trình chính quy khổ giấy A4 của Trường Cao đẳng Kinh tế TP.HCM.\n        </p>\n        <div class=\"pt-2 flex flex-wrap items-center justify-center gap-3\">\n          <button type=\"button\" onclick=\"window.print()\" class=\"bg-amber-400 hover:bg-amber-300 text-slate-950 font-bold px-5 py-2.5 rounded-xl text-xs sm:text-sm shadow-md transition-all flex items-center gap-2 cursor-pointer hover:scale-[1.02] active:scale-[0.98]\">\n            <span class=\"text-base\">🖨️</span> In Giáo Trình Toàn Tập\n          </button>\n          <button type=\"button\" onclick=\"window.print()\" class=\"bg-white hover:bg-[#FCEEEF] text-[#8B1E2D] font-bold px-5 py-2.5 rounded-xl text-xs sm:text-sm shadow-md transition-all flex items-center gap-2 cursor-pointer hover:scale-[1.02] active:scale-[0.98]\">\n            <span class=\"text-base\">📄</span> Xuất PDF Khổ Giấy A4\n          </button>\n        </div>\n      </div>\n\n    </div> <!-- /max-w-5xl -->\n\n    <!-- FLOATING ACTION BAR BÁM ĐÁY MÀN HÌNH -->\n    <div id=\"academicFloatingBar\" class=\"no-print fixed left-0 right-0 bottom-0 z-40 bg-white/95 backdrop-blur-md border-t border-[#E8E0E1] py-2 px-3 shadow-lg transition-transform duration-300\">\n      <div class=\"max-w-5xl mx-auto flex items-center justify-between gap-2\">\n        <div class=\"flex items-center gap-2 min-w-0\">\n          <span class=\"w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shrink-0\"></span>\n          <span id=\"activeChapterName\" class=\"text-xs sm:text-sm font-bold text-slate-800 truncate\">\n            Đang xem: Chương 1 — Tổng Quan Quản Trị Tài Chính\n          </span>\n        </div>\n        <div class=\"flex items-center gap-1.5 shrink-0\">\n          <a href=\"#chuong1\" class=\"p-2 sm:px-2.5 sm:py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold transition-colors\" title=\"Mục lục\">\n            ☰ Mục Lục\n          </a>\n          <button type=\"button\" id=\"btnBackToTop\" onclick=\"window.scrollTo({top: 0, behavior: 'smooth'})\" class=\"p-2 sm:px-2.5 sm:py-1.5 rounded-lg bg-[#8B1E2D] hover:bg-[#C62828] text-white text-xs font-bold transition-colors cursor-pointer\" title=\"Về đầu trang\">\n            ▲ Lên Đầu\n          </button>\n        </div>\n      </div>\n    </div>\n\n  </div> <!-- /tkd-page-scope -->\n";
